import { useEffect, useState } from "react";

import api from "../api";

import socket from "../socket";

import { useToast } from "../context/ToastContext";

import Skeleton from "../components/Skeleton";

import "../components/skeleton.css";

export default function ProviderDashboard() {

  const [bookings, setBookings] =
    useState([]);

  const [loading, setLoading] =
    useState(true);

  const { addToast } = useToast();

  // ======================================
  // GET TOKEN
  // ======================================

  const token =
    localStorage.getItem("token");

  // ======================================
  // FETCH BOOKINGS
  // ======================================

  const fetchBookings = async () => {

    try {

      setLoading(true);

      const res =
        await api.get(
          "/bookings/provider-bookings"
        );

      console.log(
        "Provider bookings:",
        res.data
      );

      setBookings(res.data || []);

    } catch (err) {

      console.log(err);

      addToast(
        "Unable to load bookings",
        "error"
      );

    } finally {

      setLoading(false);

    }

  };

  // ======================================
  // SOCKET
  // ======================================

  useEffect(() => {

    if (token) {

      socket.emit("register", {
        token
      });

    }

    fetchBookings();

    socket.on(
      "booking-created",
      (data) => {

        console.log(
          "Realtime booking:",
          data
        );

        addToast(
          `New Booking: ${data.booking.serviceName}`,
          "success"
        );

        fetchBookings();

      }
    );

    socket.on(
      "booking-update",
      () => {

        fetchBookings();

      }
    );

    return () => {

      socket.off(
        "booking-created"
      );

      socket.off(
        "booking-update"
      );

    };

  }, []);

  // ======================================
  // PROVIDER ACTION
  // ======================================

  const providerAction = async (
    bookingId,
    action
  ) => {

    try {

      await api.put(

        `/bookings/provider-action/${bookingId}`,

        { action }

      );

      addToast(
        `Booking ${action}ed`,
        "success"
      );

      fetchBookings();

    } catch (err) {

      console.log(err);

      addToast(
        "Action failed",
        "error"
      );

    }

  };

  // ======================================
  // ACTIVE BOOKINGS
  // ======================================

  const activeBookings =
    bookings.filter(

      (booking) =>

        booking.status !== "completed" &&
        booking.status !== "cancelled" &&
        booking.status !== "rejected"

    );

  // ======================================
  // UI
  // ======================================

  return (

    <div className="dashboard-container">

      <header className="dashboard-header">

        <div className="dashboard-logo">

          🚀 FastAid

        </div>

        <button

          className="logout-btn"

          onClick={() => {

            localStorage.removeItem(
              "token"
            );

            window.location.href = "/";

          }}

        >

          Logout

        </button>

      </header>

      <div className="dashboard-content">

        <h1 className="dashboard-title">

          Provider Dashboard 🛠️

        </h1>

        <p className="dashboard-subtitle">

          Manage your service requests

        </p>

        {/* ========================= */}
        {/* LOADING */}
        {/* ========================= */}

        {loading ? (

          <div style={{ marginTop: 20 }}>

            <Skeleton
              count={4}
              height="100px"
            />

          </div>

        ) : activeBookings.length === 0 ? (

          // =========================
          // NO BOOKINGS
          // =========================

          <div className="no-requests">

            <div className="no-requests-icon">
              🔔
            </div>

            <div className="no-requests-text">

              No active bookings

            </div>

          </div>

        ) : (

          // =========================
          // BOOKINGS LIST
          // =========================

          <div className="booking-list">

            {activeBookings.map(
              (booking) => (

                <div

                  key={booking._id}

                  className="booking-card"

                  style={{

                    background: "#fff",

                    padding: "20px",

                    borderRadius: "16px",

                    marginBottom: "20px",

                    boxShadow:
                      "0 4px 12px rgba(0,0,0,0.08)"

                  }}

                >

                  <h2>

                    🛠️ {
                      booking.serviceName
                    }

                  </h2>

                  <p>

                    👤 Customer:
                    {" "}
                    {
                      booking.userId?.name
                    }

                  </p>

                  <p>

                    📍 Location:
                    {" "}

                    {
                      booking.location ||
                      booking.locationDetails?.fullAddress
                    }

                  </p>

                  <p>

                    💰 Amount:
                    ₹
                    {
                      booking.servicePrice
                    }

                  </p>

                  <p>

                    📌 Status:
                    {" "}

                    <strong>

                      {
                        booking.status
                      }

                    </strong>

                  </p>

                  {/* ================= */}
                  {/* ACTION BUTTONS */}
                  {/* ================= */}

                  {(booking.status ===
                    "assigned" ||

                    booking.status ===
                    "pending") && (

                    <div
                      style={{
                        display: "flex",
                        gap: "10px",
                        marginTop: "15px"
                      }}
                    >

                      <button

                        onClick={() =>

                          providerAction(
                            booking._id,
                            "accept"
                          )

                        }

                        style={{

                          background:
                            "#10B981",

                          color: "#fff",

                          border: "none",

                          padding:
                            "10px 16px",

                          borderRadius:
                            "10px",

                          cursor:
                            "pointer"

                        }}

                      >

                        Accept

                      </button>

                      <button

                        onClick={() =>

                          providerAction(
                            booking._id,
                            "reject"
                          )

                        }

                        style={{

                          background:
                            "#EF4444",

                          color: "#fff",

                          border: "none",

                          padding:
                            "10px 16px",

                          borderRadius:
                            "10px",

                          cursor:
                            "pointer"

                        }}

                      >

                        Reject

                      </button>

                    </div>

                  )}

                </div>

              )
            )}

          </div>

        )}

      </div>

    </div>

  );

}
